.chat-history > section {
  content-visibility: auto;
  /* auto: запомнить реальную высоту после первого рендера, 600px до него */
  contain-intrinsic-size: auto 600px;
}

const box = document.querySelector('.box');
const paragraphs = document.querySelectorAll('p'); // 1000 абзацев

// Плохо: чтение и запись чередуются
for (let i = 0; i < paragraphs.length; i++) {
  // запись на прошлой итерации пометила layout грязным,
  // поэтому чтение offsetWidth заставляет пересчитать его прямо сейчас
  paragraphs[i].style.width = box.offsetWidth + 'px';
}

// Хорошо: одно чтение, потом только записи
const width = box.offsetWidth;
for (let i = 0; i < paragraphs.length; i++) {
  paragraphs[i].style.width = width + 'px';
}

function syncHeights(cards) {
  // 1. Все чтения сейчас: layout либо чистый, либо считается один раз
  const heights = cards.map((c) => c.getBoundingClientRect().height);
  const max = Math.max(...heights);

  // 2. Все записи прямо перед следующим кадром
  requestAnimationFrame(() => {
    for (const c of cards) c.style.minHeight = max + 'px';
    // здесь нельзя снова читать геометрию: это опять принудительный layout
  });
}

/* Дорого: каждый кадр проходит layout и paint на главном потоке */
@keyframes slide-bad { from { left: 0; } to { left: 300px; } }

/* Дёшево: layout и paint пропускаются, кадр собирает compositor */
@keyframes slide-good {
  from { transform: translateX(0); }
  to   { transform: translateX(300px); }
}
.drawer { animation: slide-good 300ms ease-out; }

/* Только тем немногим элементам, что реально анимируются */
.drawer.is-opening { will-change: transform; }

.chat-history > section {
  content-visibility: auto;
  /* auto: remember the real height after first render, 600px until then */
  contain-intrinsic-size: auto 600px;
}

const box = document.querySelector('.box');
const paragraphs = document.querySelectorAll('p'); // 1000 paragraphs

// Bad: reads and writes interleave
for (let i = 0; i < paragraphs.length; i++) {
  // the previous iteration's write marked layout dirty,
  // so reading offsetWidth forces it to be recalculated right now
  paragraphs[i].style.width = box.offsetWidth + 'px';
}

// Good: one read, then only writes
const width = box.offsetWidth;
for (let i = 0; i < paragraphs.length; i++) {
  paragraphs[i].style.width = width + 'px';
}

function syncHeights(cards) {
  // 1. All reads now: layout is either clean or computed once
  const heights = cards.map((c) => c.getBoundingClientRect().height);
  const max = Math.max(...heights);

  // 2. All writes right before the next frame
  requestAnimationFrame(() => {
    for (const c of cards) c.style.minHeight = max + 'px';
    // don't read geometry here again: that forces layout once more
  });
}

/* Expensive: every frame goes through layout and paint on the main thread */
@keyframes slide-bad { from { left: 0; } to { left: 300px; } }

/* Cheap: layout and paint are skipped, the compositor builds the frame */
@keyframes slide-good {
  from { transform: translateX(0); }
  to   { transform: translateX(300px); }
}
.drawer { animation: slide-good 300ms ease-out; }

/* Only on the few elements that actually animate */
.drawer.is-opening { will-change: transform; }
